<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{JobWorkerProcess,MariaDbJobQueue,MariaDbWorkerHeartbeat};
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_worker_protocol_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);
try{foreach(['invalid','oversize','no-read','list','unknown','extra','wrong-result','invalid-code','secret-result']as$i=>$mode){$p='protocol_'.$i.'_';JobsSchemaMigration::apply($db,$p);$now='2026-09-09T10:00:00.000000Z';$queue=new MariaDbJobQueue($db,$p,static fn():string=>$now,static fn():string=>str_repeat(dechex($i+1),64),['test.protocol'=>[1]]);$payload=['value'=>$mode==='no-read'?str_repeat('x',65000):$mode];$job=$queue->enqueue(['jobType'=>'test.protocol','payloadVersion'=>1,'payload'=>$payload,'availableAtUtc'=>$now,'idempotencyKey'=>sprintf('12121212-1212-4212-8212-%012d',$i+1),'actor'=>['type'=>'system','id'=>'protocol-test']]);$arrival=sys_get_temp_dir().'/fm2-protocol-'.bin2hex(random_bytes(5));putenv('JOBS_PROTOCOL_ARRIVAL='.$arrival);$command=static fn(array$j):array=>[PHP_BINARY,dirname(__DIR__).'/Support/jobs_protocol_handler.php',$mode];$worker=new JobWorkerProcess($queue,new MariaDbWorkerHeartbeat($db,$p),['test.protocol'=>[1=>$command]],static fn():string=>$now,'protocol-worker',1,10000,1);$started=microtime(true);$result=$worker->run();assertSameValue(true,microtime(true)-$started<5,'malformed protocol remains bounded '.$mode);$state=$db->query("SELECT status,result_json,failure_code FROM `{$p}fm2_jobs` WHERE job_id=".(int)$job['jobId'])->fetch_assoc();if($mode==='no-read'){assertSameValue(['stopped',0,'leased',null],[$result['status'],$result['completed'],$state['status'],$state['result_json']],'non-reading child leaves unknown lease and no result');}else{assertSameValue(['stopped','ready',null,'JOB_HANDLER_FAILED'],[$result['status'],$state['status'],$state['result_json'],$state['failure_code']],$mode.' output maps safe retry');}if(is_file($arrival)){$pid=(int)file_get_contents($arrival);assertSameValue(false,@posix_kill($pid,0),'protocol child reaped '.$mode);unlink($arrival);}putenv('JOBS_PROTOCOL_ARRIVAL');}echo"PASS: JOBS-WORKER-RUNTIME-001 bounded handler protocol\n";
}finally{putenv('JOBS_PROTOCOL_ARRIVAL');$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}

